/*
  Readings for the 29 test cases: 37759 (1. Case 20044587: 1055, 10. Case 27505812: 566, 11. Case 29366372: 435, 2. Case 20297618: 517, 20. Case 22995465: 488, 21. Case 23473524: 4104, 22. Case 23488445: 473, 23. Case 23819016: 733, 24. Case 23831430: 6886, 25. Case 24181354: 1627, 26. Case 27617929: 1771, 27. Case 28662225: 5368, 28. Case 29279905: 1293, 29. Case 29974575: 3365, 3. Case 20626031: 1285, 4. Case 21255400: 2648, 5. Case 22342963: 1778, 6. Case 22580999: 488, 7. Case 24490144: 666, 8. Case 25926192: 939, 9. Case 27089790: 1274).
  Generated by models/hospital/readings_to_sql.py (rules in its docstring). Run after assignments.sql, substeps.sql and
  authorisation/execution_properties.sql.
  Each row is one chart entry: the assignment (the spec, the person's job node, the person), where it was taken (NodeId: the
  substep, else the step), the property and its tag or Value, when it was charted (CreationDate). DirectedEdgeId NULL.
  Replaces the test cases' earlier readings (@Reset = 1). If an assignment, node, property or tag can't be found, the script
  lists them and writes nothing. Set @Commit = 0 for a dry run.
*/
USE [3b30813b-994f-4bb1-a70f-9763e2b61154];
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Commit             bit              = 1;     -- 0 = dry run
DECLARE @Reset              bit              = 1;     -- 1 = replace the test cases' earlier readings
DECLARE @OrganisationId     uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @AuthOrganisationId int              = 12;
DECLARE @ResultId           int              = 45;
DECLARE @CreatedBy          uniqueidentifier = 'A01AE24F-0301-4198-9036-8CC58F070B01';

DECLARE @rows TABLE (SpecName nvarchar(400), TeamName nvarchar(200), JobName nvarchar(200), ExecutorEmail nvarchar(256),
                     AtJob nvarchar(200), AtTeam nvarchar(200), StepIndex int, SubIndex int NULL, PropertyName nvarchar(200),
                     TagName nvarchar(200) NULL, Value nvarchar(100) NULL, CreationDate datetime2,
                     SpecId uniqueidentifier NULL, NodeId int NULL, ExecutorGuid uniqueidentifier NULL, ExecutorInt int NULL,
                     TakenAtNodeId int NULL, PropertyKey nvarchar(50) NULL, TagKey nvarchar(50) NULL,
                     TagGuid uniqueidentifier NULL);

-- The spec, the assignment's job node and executor.
UPDATE r SET SpecId = s.Id FROM @rows r
JOIN [Results].dbo.Specs s ON s.Name COLLATE DATABASE_DEFAULT = r.SpecName COLLATE DATABASE_DEFAULT
                         AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;
DECLARE @jobNodes TABLE (Job nvarchar(200), Team nvarchar(200), NodeId int);
SELECT j.Job, j.Team, MIN(jn.Id)
FROM (SELECT JobName AS Job, TeamName AS Team FROM @rows UNION SELECT AtJob, AtTeam FROM @rows) j
JOIN [Authorisation].dbo.SkillSets tk ON tk.Name COLLATE DATABASE_DEFAULT = j.Team COLLATE DATABASE_DEFAULT
                                     AND tk.NetworkId = 1 AND tk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes tn ON tn.SkillSetId = tk.Guid AND tn.NetworkId = 1 AND tn.OrganisationId = @OrganisationId
JOIN [Authorisation].dbo.SkillSets jk ON jk.Name COLLATE DATABASE_DEFAULT = j.Job COLLATE DATABASE_DEFAULT
                                     AND jk.NetworkId = 2 AND jk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes jn ON jn.SkillSetId = jk.Guid AND jn.NetworkId = 2 AND jn.ParentNodeId = tn.Id AND jn.OrganisationId = @OrganisationId
GROUP BY j.Job, j.Team;
UPDATE r SET NodeId = j.NodeId FROM @rows r JOIN @jobNodes j ON j.Job = r.JobName AND j.Team = r.TeamName;
UPDATE r SET ExecutorGuid = u.Guid, ExecutorInt = u.Id FROM @rows r
JOIN [Authorisation].dbo.Users u ON u.Email COLLATE DATABASE_DEFAULT = r.ExecutorEmail COLLATE DATABASE_DEFAULT
                                AND u.OrganisationId = @AuthOrganisationId;

-- Where it was taken: the step (NetworkId 3) of the record's job node, and its substep (NetworkId 4) where there is one.
UPDATE r SET TakenAtNodeId = ISNULL(ss.Id, sn.Id) FROM @rows r
JOIN @jobNodes aj ON aj.Job = r.AtJob AND aj.Team = r.AtTeam
JOIN dbo.Nodes sn ON sn.NetworkId = 3 AND sn.ParentNodeId = aj.NodeId AND sn.HorizontalIndex = r.StepIndex
                 AND sn.OrganisationId = @OrganisationId
LEFT JOIN dbo.Nodes ss ON r.SubIndex IS NOT NULL AND ss.NetworkId = 4 AND ss.ParentNodeId = sn.Id
                      AND ss.HorizontalIndex = r.SubIndex AND ss.OrganisationId = @OrganisationId
WHERE r.SubIndex IS NULL OR ss.Id IS NOT NULL;

-- The property and its tag.
UPDATE r SET PropertyKey = CONVERT(nvarchar(50), p.Id) FROM @rows r
JOIN [Authorisation].dbo.Properties p ON p.Name COLLATE DATABASE_DEFAULT = r.PropertyName COLLATE DATABASE_DEFAULT
                                     AND p.OrganisationId = @AuthOrganisationId AND p.PropertySubjectTypeId = 1;
UPDATE r SET TagKey = CONVERT(nvarchar(50), a.Id), TagGuid = a.Guid FROM @rows r
JOIN [Authorisation].dbo.PropertyAttributes a ON CONVERT(nvarchar(50), a.PropertyId) = r.PropertyKey
                                             AND a.Name COLLATE DATABASE_DEFAULT = r.TagName COLLATE DATABASE_DEFAULT
WHERE r.TagName IS NOT NULL;

-- AssignmentId and PropertyAttributeId take a Guid or an Id, whichever their columns are (a tag's Guid only where its Id isn't one).
DECLARE @isGuid TABLE (Col sysname, IsGuid bit);
SELECT c.name, CASE WHEN t.name = 'uniqueidentifier' THEN 1 ELSE 0 END
FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
WHERE (c.object_id = OBJECT_ID('dbo.ExecutionProperties') AND c.name IN ('AssignmentId', 'PropertyAttributeId'))
   OR (c.object_id = OBJECT_ID('dbo.Assignments') AND c.name = 'ExecutorId');
DECLARE @byGuid  bit = (SELECT IsGuid FROM @isGuid WHERE Col = 'ExecutorId');
DECLARE @asGuid  bit = (SELECT IsGuid FROM @isGuid WHERE Col = 'AssignmentId');
DECLARE @tagGuid bit = CASE WHEN (SELECT IsGuid FROM @isGuid WHERE Col = 'PropertyAttributeId') = 1
                              AND (SELECT TYPE_NAME(system_type_id) FROM [Authorisation].sys.columns
                                   WHERE object_id = OBJECT_ID('[Authorisation].dbo.PropertyAttributes') AND name = 'Id') <> 'uniqueidentifier'
                             THEN 1 ELSE 0 END;
IF OBJECT_ID('tempdb..#reading_rows') IS NOT NULL DROP TABLE #reading_rows;
SELECT * INTO #reading_rows FROM @rows;
ALTER TABLE #reading_rows ADD AssignmentKey nvarchar(50) NULL;
DECLARE @find nvarchar(max) = N'
UPDATE r SET AssignmentKey = CONVERT(nvarchar(50), ' + CASE WHEN @asGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N')
FROM #reading_rows r JOIN dbo.Assignments a ON a.SpecId = r.SpecId AND a.NodeId = r.NodeId
 AND a.ExecutorId = ' + CASE WHEN @byGuid = 1 THEN N'r.ExecutorGuid' ELSE N'r.ExecutorInt' END + N';';
EXEC sp_executesql @find;

IF EXISTS (SELECT 1 FROM #reading_rows WHERE AssignmentKey IS NULL OR TakenAtNodeId IS NULL OR PropertyKey IS NULL
                                  OR (TagName IS NOT NULL AND TagKey IS NULL))
BEGIN
    SELECT DISTINCT TOP (50) SpecName, JobName, TeamName, ExecutorEmail, StepIndex, SubIndex, PropertyName, TagName,
           CASE WHEN SpecId IS NULL THEN 'spec not found (run the test cases)'
                WHEN NodeId IS NULL OR ExecutorGuid IS NULL OR AssignmentKey IS NULL THEN 'assignment not found (run assignments.sql)'
                WHEN TakenAtNodeId IS NULL THEN 'step or substep not found (run process.sql, substeps.sql)'
                WHEN PropertyKey IS NULL THEN 'property not found (run authorisation/execution_properties.sql)'
                ELSE 'tag not found (run authorisation/execution_properties.sql)' END AS Problem
    FROM #reading_rows WHERE AssignmentKey IS NULL OR TakenAtNodeId IS NULL OR PropertyKey IS NULL
                  OR (TagName IS NOT NULL AND TagKey IS NULL);
    DROP TABLE #reading_rows;
    RAISERROR('Some assignments, nodes, properties or tags could not be found (see grid): nothing written.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

DECLARE @removed int = 0, @added int = 0;
IF @Reset = 1
BEGIN
    DECLARE @clear nvarchar(max) = N'
    DELETE x FROM dbo.ExecutionProperties x JOIN dbo.Assignments a ON x.AssignmentId = ' +
        CASE WHEN @asGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N'
    WHERE a.SpecId IN (SELECT DISTINCT SpecId FROM #reading_rows);
    SELECT @removed = @@ROWCOUNT;';
    EXEC sp_executesql @clear, N'@removed int OUTPUT', @removed OUTPUT;
END

DECLARE @insert nvarchar(max) = N'
                                     ModificationDate, CreatedBy, ModifiedBy)
SELECT r.AssignmentKey, r.TakenAtNodeId, NULL, r.PropertyKey, ' + CASE WHEN @tagGuid = 1 THEN N'r.TagGuid' ELSE N'r.TagKey' END + N',
       r.Value, r.CreationDate, NULL, @CreatedBy, NULL
FROM #reading_rows r;
SELECT @added = @@ROWCOUNT;';
EXEC sp_executesql @insert, N'@CreatedBy uniqueidentifier, @added int OUTPUT', @CreatedBy, @added OUTPUT;

SELECT @removed AS ReadingsRemoved, @added AS ReadingsAdded;
SELECT SpecName, PropertyName, COUNT(*) AS Readings FROM #reading_rows GROUP BY SpecName, PropertyName ORDER BY SpecName, COUNT(*) DESC;
DROP TABLE #reading_rows;

IF @Commit = 1 BEGIN COMMIT TRANSACTION;   PRINT 'Committed.'; END
ELSE           BEGIN ROLLBACK TRANSACTION; PRINT 'Dry run: rolled back.'; END
